BOOL ReadScopeList(wStream* s, SCOPE_LIST* scopeList)
{
    UINT32 scopeCount;
    size_t requiredSize;
    LICENSE_BLOB** blobs;
    int i;

    if (!Stream_CheckAndLogRequiredLength(s, 4))
        return FALSE;

    Stream_Read_UINT32(s, scopeCount);

    requiredSize = scopeCount * sizeof(LICENSE_BLOB*);
    if (!Stream_CheckAndLogRequiredLength(s, requiredSize))
        return FALSE;

    blobs = (LICENSE_BLOB**)malloc(scopeCount * sizeof(LICENSE_BLOB*));
    if (!blobs)
        return FALSE;

    for (i = 0; i < scopeCount; i++)
    {
        blobs[i] = (LICENSE_BLOB*)malloc(sizeof(LICENSE_BLOB));
        if (!blobs[i])
        {
            while (i > 0)
            {
                free(blobs[i - 1]);
                i--;
            }
            free(blobs);
            return FALSE;
        }

        if (!ReadLicenseBlob(s, blobs[i]))
        {
            while (i > 0)
            {
                free(blobs[i - 1]);
                i--;
            }
            free(blobs);
            return FALSE;
        }
    }

    scopeList->count = scopeCount;
    scopeList->blobs = blobs;

    return TRUE;
}

BOOL ReadLicenseScopes(wStream* s, SCOPE_LIST* scopeList)
{
    UINT32 scopeCount;
    UINT32 i;
    size_t size;

    if (Stream_GetRemainingLength(s) < 4)
        return FALSE;

    InStream_Read_UINT32(s, scopeCount);

    size = scopeCount * sizeof(LICENSE_BLOB);

    if (Stream_GetRemainingLength(s) < size)
        return FALSE;

    scopeList->scopeCount = scopeCount;
    scopeList->scopes = (LICENSE_BLOB*)malloc(size);

    if (!scopeList->scopes)
        return FALSE;

    for (i = 0; i < scopeCount; i++)
    {
        if (!ReadLicenseBlob(s, &scopeList->scopes[i]))
            return FALSE;
    }

    return TRUE;
}

BOOL ReadLicenseScopes(wStream* s, SCOPE_LIST* scopeList)
{
    UINT32 scopeCount;
    size_t totalSize;
    size_t index;

    if (Stream_GetRemainingLength(s) < 4)
        return FALSE;

    InStream_Read_UINT32(s, scopeCount);

    if (scopeCount == 0)
        return FALSE;

    totalSize = scopeCount * sizeof(LICENSE_BLOB);

    if (Stream_GetRemainingLength(s) < totalSize)
        return FALSE;

    scopeList->count = scopeCount;
    scopeList->scopes = (LICENSE_BLOB*)malloc(totalSize);

    if (!scopeList->scopes)
        return FALSE;

    for (index = 0; index < scopeCount; index++)
    {
        LICENSE_BLOB* blob = &scopeList->scopes[index];

        if (Stream_GetRemainingLength(s) < sizeof(LICENSE_BLOB))
        {
            free(scopeList->scopes);
            scopeList->scopes = NULL;
            return FALSE;
        }

        InStream_Read(s, &blob->data, sizeof(blob->data));
        blob->size = sizeof(blob->data);
    }

    return TRUE;
}

